coding.solution:
def saturation_point(steps):
    for prev, cur in zip(steps, steps[1:]):
        tp_gain = (cur[1] - prev[1]) / prev[1]
        p95_gain = (cur[2] - prev[2]) / prev[2]
        if tp_gain < 0.10 and p95_gain > 0.50:
            return prev[0]
    return steps[-1][0]

