coding.solution:
def regressions(baseline, current, tolerance_pct):
    out = []
    for label, base in baseline.items():
        if label not in current:
            out.append(f'{label} (missing)')
        elif current[label] > base * (1 + tolerance_pct / 100):
            out.append(label)
    return sorted(out)
